static class NumExt {

  public static int Doubled(this int self) {
    return self * 2;
  }

  public static int Plus(this int self, int by) {
    return self + by;
  }

}

class Foo {

  void test(int a) {
    var b = a.Doubled();
    var c = a.Plus(1);
    print("b: " + b + " ; c: " + c);
  }
}
